        char = json_str[i]

        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == '"':
            return parse_string()
        elif char.isdigit() or char in ('-', '.'):
            return parse_number()
        elif char == 't':
            return parse_true()
        elif char == 'f':
            return parse_false()
        elif char == 'n':
            return parse_null()
        else:
            raise ValueError("Invalid character in JSON string")

    def parse_object():
        nonlocal i
        if json_str[i] != '{':
            raise ValueError("Expected '{' at the beginning of an object")
        i += 1

        obj = {}
        while i < len(json_str) and json_str[i] != '}':
            key = parse_string()
            if i >= len(json_str) or json_str[i] != ':':
                raise ValueError("Expected ':' after key in object")
            i += 1
            value = parse_value()
            obj[key] = value
            if i < len(json_str) and json_str[i] == ',':
                i += 1
        if i >= len(json_str) or json_str[i] != '}':
            raise ValueError("Expected '}' at the end of an object")
        i += 1
        return obj

    def parse_array():
        nonlocal i
        if json_str[i] != '[':
            raise ValueError("Expected '[' at the beginning of an array")
        i += 1

        arr = []
        while i < len(json_str) and json_str[i] != ']':
